import{_ as r,o,c as a,a2 as e}from"./chunks/framework.BWuWLRhz.js";const c=JSON.parse('{"title":"一般","description":"","frontmatter":{},"headers":[],"relativePath":"ja-JP/user-guide/settings/general.md","filePath":"ja-JP/user-guide/settings/general.md","lastUpdated":1787287369000}'),s={name:"ja-JP/user-guide/settings/general.md"};function n(i,t,l,g,p,h){return o(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="一般" tabindex="-1">一般 <a class="header-anchor" href="#一般" aria-label="Permalink to &quot;一般&quot;">​</a></h1><p>6 つのタブがあります: <strong>システム</strong>、<strong>クイック検索ウィンドウ</strong>、<strong>フル検索ウィンドウ</strong>、<strong>プレビュー</strong>、<strong>クイックナビゲーション</strong>、<strong>プレビューとサムネイル</strong>。</p><h2 id="システム" tabindex="-1">システム <a class="header-anchor" href="#システム" aria-label="Permalink to &quot;システム&quot;">​</a></h2><ul><li><strong>Windows 起動時に Lertaro を起動</strong> — チェックボックス。サインイン時に Lertaro を起動します。</li><li><strong>起動時にアップデートを自動確認</strong> — チェックボックス。</li><li><strong>新しいバージョンが検出されたらサイレントで自動更新</strong> — チェックボックス。上のチェックがオンの場合のみ有効になります。確認なしでバックグラウンドでアップデートをダウンロードしてインストールします。</li><li><strong>ハードウェアアクセラレーションを有効にする</strong> — チェックボックス。デフォルトでオンです。オフにすると、クイック検索ウィンドウは Direct3D を使わずソフトウェアで描画されるようになります。これは、Lertaro の実行中に NVIDIA Advanced Optimus が GPU のホットスイッチを拒否する問題を回避するためのものです(影響を受けるのはクイックウィンドウのみで、アプリ全体ではありません)。反映には Lertaro の再起動が必要です。</li><li><strong>タスクトレイアイコンを非表示にする</strong> — チェックボックス。デフォルトでオフです。即座に適用され、再起動は不要です。タスクトレイアイコンの右クリックで表示されるのと同じメニューは、この設定に関わらず常に <a href="./../hotkeys.html#検索ボックスのロゴアイコン">クイックウィンドウ自身のロゴ</a> から利用できるため、トレイアイコンを非表示にしても設定や終了への導線を失うことはありません。</li><li><strong>Everything IPC エミュレーションを有効化</strong> — チェックボックス。デフォルトでオフです。Directory Opus、Total Commander、Flow Launcher など Everything に依存するサードパーティ製ツールが、Lertaro のインメモリ インデックスを使用して検索やフォルダー サイズ計算をシームレスに行えるようにします。</li><li><strong>あいまい一致を有効化</strong> — チェックボックス。デフォルトでオンです。オンのとき、通常の検索語はその文字が名前のどこかに順番どおりに出現するだけで一致します。オフにすると、通常の検索語は連続した部分文字列として現れる必要があります(<code>abc</code> は <code>a-b-c</code> に一致しなくなります)——何が変わり何が変わらないかは<a href="./../search-syntax.html#あいまい検索-既定">検索構文</a>を参照してください。即座に適用され、再起動は不要です。</li><li><strong>クエリトークン全体プレフィックス文字</strong> — テキストボックス（最大 1 文字、デフォルト <code>:</code>）。検索ボックス末尾のトークン式を分割する全体プレフィックス文字を設定します。パス除外およびカスタムフィルターのプレフィックス文字は <strong>設定 → プラグイン → CoreExtensions</strong> で個別に設定可能です。</li><li><strong>ログレベル</strong> — ドロップダウン: エラー / 警告 / 情報 (デフォルト) / デバッグ。App、Service、Hook の各ログの詳細度を制御します(<a href="./service-status.html">サービスの状態</a> を参照)。</li><li><strong>インターフェース言語</strong> — ドロップダウン。インストール済みのすべての翻訳プロバイダー(組み込みの言語に加え、プラグインが追加するもの)から生成されます。</li></ul><p>テーマの選択は独立した <a href="./appearance.html">外観</a> セクションに移動しました。テーマピッカーや「Windows のライト/ダーク設定に従う」オプションについてはそちらのページを参照してください。</p><h2 id="クイック検索ウィンドウ" tabindex="-1">クイック検索ウィンドウ <a class="header-anchor" href="#クイック検索ウィンドウ" aria-label="Permalink to &quot;クイック検索ウィンドウ&quot;">​</a></h2><p>クイック検索バーの外観と、検索結果の優先順位付けの両方を扱います。</p><p><strong>検索バーのレイアウト</strong> — クイック検索バーのサイズと画面上の位置をカスタマイズします:</p><ul><li><strong>検索バーの幅 (px)</strong> — 範囲 300–1200px、デフォルト 570px。</li><li><strong>検索バーの高さ (px)</strong> — 範囲 45–120px、デフォルト 60px。この数値は結果行のアイコンサイズ、名前/パスのフォントサイズ、行の高さ (<code>height / 60</code>) も決定するため、検索バーを高くすると結果リスト全体も同じ比率で拡大されます。</li><li><strong>検索ボックスに時計を表示</strong> — チェックボックス。デフォルトでオフです。検索ボックスが空の間、通常の「入力して検索...」のプレースホルダーテキストの代わりに、現在の日付、曜日、時刻を表示します。入力を始めた瞬間、置き換えられていたプレースホルダーと同様に消えます。クイックウィンドウのみが対象で、インライン検索ウィンドウはこれがオンでも常に通常のプレースホルダーを表示します。</li><li><strong>ホットキーの再押下でフルウィンドウとして再表示</strong> — チェックボックス。デフォルトでオフです。通常、クイックウィンドウが開いている状態でトグルホットキーをもう一度押すと単に非表示になりますが、これをオンにすると 2 回目の押下でフルウィンドウへの切り替えになります(すでに入力していたクエリはそのまま引き継がれます)。何かを閉じる代わりに、切り替えが行われます。</li><li><strong>位置を固定する</strong> — チェックボックス。デフォルトでオフです。オンにするとクイックウィンドウをドラッグできなくなり、誤ってつかんで置いた場所からずれてしまうのを防ぎます。ロゴを右クリックしての位置リセットは引き続き使えます。下の <strong>レイアウト設定をリセット</strong> も、この固定を他の設定とまとめて解除します。</li><li><strong>レイアウト設定をリセット</strong> ボタン — 上記 5 つの設定をすべてデフォルトに戻します。</li></ul><p><a href="./../hotkeys.html#検索ボックスのロゴアイコン">クイックウィンドウのロゴ</a> を右クリックすると、画面上の位置だけ(サイズは変わりません)がリセットされ、初回起動時と同じ方法で中央に再配置されます。</p><p><strong>結果タイプの優先順位</strong> — 下の <a href="#クイックナビゲーション">クイックナビゲーション</a> と同じ上下矢印(またはドラッグで並べ替え)リストです。結果タイプ(アプリケーション、設定、ファイルフィルター、サードパーティプラグイン独自の検索対象アイテム、または組み込みの「ファイル」エントリ)を上下に移動すると、クエリテキストとの一致度に関わらず、クイックウィンドウの検索結果で常にその下のタイプより優先されるようになります。履歴とお気に入りは常に先頭に表示され、このリストには含まれません。</p><p>各タイプには専用の 1 文字の <strong>トリガー</strong>(任意、行ごとに 1 つのテキストボックス)を設定できます。クイックウィンドウの先頭にその文字を入力すると、そのタイプの結果だけが表示され、他はすべて隠されます。例については <a href="./../search-syntax.html#検索結果種別トリガー">検索構文</a> を参照してください。トリガーだけを入力してまだ何も続けて入力していない場合は、「検索結果はありません」ではなく「入力を続けて X のみを検索」というプロンプトが表示されます。一度あるタイプに割り当てられると予約されるため、実際の検索を始めるときに使いそうにない文字を選んでください。句読点文字(例: <code>;</code>)の方が、スペース単体よりも確実に機能します。何も入力していない状態でのスペース単体は空の検索ボックスと同じ扱いになり、そのプロンプトは表示されません。</p><h2 id="フル検索ウィンドウ" tabindex="-1">フル検索ウィンドウ <a class="header-anchor" href="#フル検索ウィンドウ" aria-label="Permalink to &quot;フル検索ウィンドウ&quot;">​</a></h2><p>フル/メイン検索ウィンドウ(タスクバーやスタートメニューのショートカットから開く大きい方のウィンドウで、クイックポップアップとは異なります。<a href="./../getting-started.html#_3-つのウィンドウ">はじめに</a> を参照)のデフォルトサイズを設定します:</p><ul><li><strong>ウィンドウの幅 (px)</strong> — 範囲 640–2000px、デフォルト 854px。</li><li><strong>ウィンドウの高さ (px)</strong> — 範囲 400–1400px、デフォルト 480px。最小値はウィンドウ自体のリサイズ下限と一致しているため、設定した値がウィンドウ自身によって暗黙に上書きされることはありません。</li><li><strong>検索ウィンドウ設定をリセット</strong> ボタン。</li><li><strong>フル検索ウィンドウを 1 つだけ許可する</strong> — チェックボックス、既定ではオフです。オフのときは独立したフルウィンドウを複数開けます。有効にすると、フルウィンドウを再度開いたときは新しいウィンドウを作らず、既存のウィンドウをアクティブにします。クイックウィンドウの<strong>さらに表示</strong>からクエリを引き継ぐ場合、そのクエリは既存ウィンドウのクエリを置き換えます。</li></ul><p>ウィンドウの端をドラッグして手動でリサイズすると、その状態は自動的に記憶されます。次にウィンドウを開いたとき(または新しいウィンドウを開いたとき)、最後に残したサイズで表示され、このページのフィールドもそれに合わせて更新されます。最大化した状態でのリサイズは記憶されたサイズを上書きしません。通常(最大化されていない)状態でのリサイズのみが記憶されます。</p><p>フルウィンドウの結果リストには、お気に入りや履歴のリコール項目は追加されません。個人向けのリコール結果はクイックウィンドウとインラインウィンドウだけに残り、フルウィンドウでは有効な検索プロバイダーによる通常の関連度順が維持されます。</p><p><strong>結果グリッドの列順序</strong> — Settings の他の場所で使われているのと同じ並べ替えリストです(<a href="./favorites.html">お気に入り</a> を参照)。結果グリッドの列(名前、パス、更新日時、またはプラグインが提供する任意の列)を左右に移動します。グリッド/テーブル形式の結果レイアウトにのみ影響し、コンパクトリストレイアウトには並べ替える列がありません。</p><p><strong>サイドバーフィルターの順序</strong> — 同じ仕組みで、サイドバーのフィルターグループ(種類、更新日時、プラグインが追加した任意のグループ)が表示される順序を設定します。</p><p>フル検索の実行中は、サイドバーの各フィルターに現在のクエリに一致する件数がリアルタイムで表示されます。結果が届くたびに更新され、クエリを変更するとリセットされます。現在選択しているフィルターの影響は受けません。サイドバーの幅は最も長いフィルター名と件数に合わせて自動調整されるため、名前は折り返されず完全に表示されます。</p><p><strong>アクションメニューのセクション順序</strong> — 同じ仕組みで、<a href="./../actions-and-preview.html#アクションメニュー">アクションメニュー</a> の各セクション(組み込みのアクショングループと、そこにアクションを提供する各プラグインのセクション。例: カスタムアクション、または Windows シェルの右クリックメニュー)が表示される順序を設定します。まだこのリストにないセクションは、標準の位置(組み込みが最初、その後にプラグインのセクションが提供された順)にフォールバックします。</p><p>結果グリッドの列ヘッダーをクリックすると、昇順、降順、そして 3 回目のクリックでデフォルトの関連度順にリセットされる、という 3 つの状態を順に切り替わります(この時ヘッダーのソート矢印は消えます)。これは Lertaro が実行され続けている間だけ記憶されます。アプリを終了する(ウィンドウを閉じるだけでなく)と、次に開いたときにソート順はデフォルトにリセットされます。これは、永続的に保存される上記の列/サイドバー順序とは異なります。</p><h2 id="プレビュー" tabindex="-1">プレビュー <a class="header-anchor" href="#プレビュー" aria-label="Permalink to &quot;プレビュー&quot;">​</a></h2><ul><li><strong>プレビューの幅 (px)</strong> — 範囲 250–900px。</li><li><strong>プレビューの高さ (px)</strong> — 範囲 250–1200px、デフォルトは一般的なディスプレイでペインが過度に縦長にならないサイズです。</li><li><strong>プレビューウィンドウ設定をリセット</strong> ボタン。</li></ul><p>プレビューウィンドウは現在の結果件数を無視します。コンテンツに合わせて大きくなるサイズではなく、固定サイズです。ペインの配置方法については <a href="./../actions-and-preview.html">アクションメニューとプレビュー</a> を参照してください。</p><h2 id="クイックナビゲーション" tabindex="-1">クイックナビゲーション <a class="header-anchor" href="#クイックナビゲーション" aria-label="Permalink to &quot;クイックナビゲーション&quot;">​</a></h2><p><a href="./../hotkeys.html#クイックナビゲーション-マウス">クイックナビゲーション</a> メニューのルートレベルのセクションが表示される順序を設定します。これは提供元(例: お気に入り/履歴/設定済みフォルダー、Total Commander の Directory Hotlist、Directory Opus のお気に入り、プラグイン独自のクイックナビゲーションエントリ)ごとに 1 つのセクションがあり、それぞれ独自のヘッダーでラベル付けされます。</p><p><strong>プロバイダーの順序</strong> — Settings の他の場所で使われているのと同じ上下矢印(またはドラッグで並べ替え)リストです(<a href="./favorites.html">お気に入り</a> を参照)。プロバイダーを上下に移動すると、他のセクションと比較したときのそのセクションの位置が変わります。現在有効になっているプラグインコンポーネントのプロバイダーのみがここに表示されます。<a href="./plugins.html">プラグイン</a> で無効化されているものは、そもそもメニューの候補にならないため、並べ替える対象にもなりません。</p><h2 id="プレビューとサムネイル" tabindex="-1">プレビューとサムネイル <a class="header-anchor" href="#プレビューとサムネイル" aria-label="Permalink to &quot;プレビューとサムネイル&quot;">​</a></h2><p>それぞれが独立した 2 つの優先順位リストで、各プロバイダーが自身の役割で最初に処理する権利を得るかどうかを決めます。通常はプロバイダーを完全に無効化する以外に変更する方法がない、各プロバイダー固有の固定された組み込みの優先順位だけで決まります。</p><p><strong>ファイルプレビュープロバイダーの順序</strong> — <a href="./../actions-and-preview.html#quicklook-プレビュー">ファイルプレビュープロバイダー</a> 用です(例えば、<a href="./../actions-and-preview.html#quicklook-による外部プレビュー-任意">QuickLook Bridge</a> プラグインは、組み込みのすべてのプレビューアより自身の優先順位を上に設定します)。Settings の他の場所で使われているのと同じ上下矢印(またはドラッグで並べ替え)リストです(<a href="./favorites.html">お気に入り</a> を参照)。プロバイダーを上に移動すると、その組み込みの優先順位に関わらず、常に下のプロバイダーより優先されるようになります。現在有効になっているプラグインコンポーネントのプロバイダーのみがここに表示されます。<a href="./plugins.html">プラグイン</a> で無効化されているものは、どのみち何もプレビューしないためです。</p><p><strong>サムネイルプロバイダーの順序</strong> — 同じ仕組みで、(プレビューペインではなく)検索結果リスト自体に表示されるアイコン/サムネイルについてのものです。現在組み込みのプロバイダーは 1 つしかないため、複数のプラグインがカスタムサムネイルプロバイダーを実装するようになった場合に特に意味を持ちます。</p>',32)])])}const u=r(s,[["render",n]]);export{c as __pageData,u as default};
